function UIBattleEndStarMission:SetStarMissionDescription()
    local questId = BattleEndMgr.questId -- 当前关卡 ID
    local starInfo = BattleEndMgr:GetStarConditionData() -- 三星条件数据
    local _, conditionData = QuestConfMgr:GetInstance():GetQuestConditions(questId)
    -- print("->UIBattleEndStarMission:SetStarMissionDescription:", isNull(starInfo) and "" or table.dump(starInfo))
    if starInfo and table.count(checkTable(starInfo)) > 0 then
        for i, v in ipairs(starInfo) do
            local conditionNode = CS.UnityEngine.GameObject.Instantiate(self.MissionFinishPoint, self.Root_MissionCompletedProccess)
            if not IsNull(conditionNode) then
                conditionNode.name = "MissionFinishPoint"..tostring(i)      -- 动画会按照这个名字找节点
                --- 完成状态 Icon
                local trans_finishIcon = conditionNode.transform:Find("Img_MissionFinishIcon")
                if not IsNull(trans_finishIcon) then
                    local si_finishIcon = trans_finishIcon.gameObject:GetComponent(typeof(CS.Game.Native.Common.UISwitchImage))
                    if not IsNull(si_finishIcon) then
                        local isFinish = checkNumber(v.status) == 1
                        si_finishIcon.Status = isFinish and 2 or 1
                        si_finishIcon:Reset()
                        
                    end
                end
                --- 三星任务描述
                local trans_condition = conditionNode.transform:Find("Txt_MissionDes")
                if not IsNull(trans_condition) then
                    local txt_condition = trans_condition.gameObject:GetComponent(typeof(CS.UnityEngine.UI.Text))
                    if not IsNull(txt_condition) then
                        if conditionData and conditionData[i] then
                            local _CD =  conditionData[i].desc -- ConditionDescription
                            txt_condition.text = _CD
                            local stComp = txt_condition.gameObject:GetComponent(typeof(CS.Game.Native.Common.UISwitchText))
                            if not IsNull(stComp) then
                                local isFinish = checkNumber(v.status) == 1
                                stComp.Status = isFinish and 2 or 1
                                stComp:Reset()
                            end
                        end
                    end
                end

                -- 完成特效
                local trans_light = conditionNode.transform:Find("Img_Light")
                if isNotNull(trans_light) then
                    local isFinish = checkNumber(v.status) == 1
                    KTool.SetActive(trans_light, isFinish)
                end
                
                --- 节点状态
                KTool.SetActive(conditionNode, true)
            end
        end
    end
end

---SetDefeatTips
---关卡失败提示
function UIBattleEndStarMission:SetDefeatTips()
    local _tipsWords = {
        [1] = localize("注重战中策略, 达成关卡目标") }
    for i, description in ipairs(_tipsWords) do
        local conditionNode = CS.UnityEngine.GameObject.Instantiate(self.MissionFinishPoint, self.Root_MissionCompletedProccess)
        if not IsNull(conditionNode) then
            local trans_finishIcon = conditionNode.transform:Find("Img_MissionFinishIcon")
            if not IsNull(trans_finishIcon) then
                local si_finishIcon = trans_finishIcon.gameObject:GetComponent(typeof(CS.Game.Native.Common.UISwitchImage))
                if not IsNull(si_finishIcon) then
                    si_finishIcon.Status = 1
                    si_finishIcon:Reset()
                end
            end
            local trans_condition = conditionNode.transform:Find("Txt_MissionDes")
            if not IsNull(trans_condition) then
                local txt_condition = trans_condition.gameObject:GetComponent(typeof(CS.UnityEngine.UI.Text))
                if not IsNull(txt_condition) then
                    txt_condition.text = description
                    local stComp = txt_condition.gameObject:GetComponent(typeof(CS.Game.Native.Common.UISwitchText))
                    if not IsNull(stComp) then
                        stComp.Status = 1
                        stComp:Reset()
                    end
                end
            end
        end
        KTool.SetActive(conditionNode, true)
    end
end

